#include <stdio.h>

#define V 5
#define INF 0x3f3f3f3f

int g[V][V];
int lowcost[V];      /* 到当前树的最小边权 */
int adj[V];          /* 对应邻接点 */
int inTree[V];

int main(void) {
    for (int i = 0; i < V; i++)
        for (int j = 0; j < V; j++)
            g[i][j] = (i == j) ? 0 : INF;

    int edges[][3] = {{0,1,4},{0,2,3},{1,2,1},{1,3,2},{2,3,4},{3,4,2},{2,4,5}};
    int m = (int)(sizeof(edges) / sizeof(edges[0]));
    for (int i = 0; i < m; i++) {
        int u = edges[i][0], v = edges[i][1], w = edges[i][2];
        g[u][v] = g[v][u] = w;
    }

    for (int i = 0; i < V; i++) { lowcost[i] = INF; adj[i] = -1; inTree[i] = 0; }

    int start = 0;
    lowcost[start] = 0;
    int total = 0;

    printf("Prim 朴素版，从 %d 出发：\n", start);
    for (int round = 0; round < V; round++) {
        int u = -1, best = INF;
        for (int i = 0; i < V; i++)
            if (!inTree[i] && lowcost[i] < best) { best = lowcost[i]; u = i; }
        if (u == -1) break;

        inTree[u] = 1;
        total += lowcost[u];
        if (adj[u] == -1) {
            printf("  第 %d 轮：加入起点 %d（无入边，累计=%d）\n", round + 1, u, total);
        } else {
            printf("  第 %d 轮：加入 %d，选边 (%d-%d, w=%d)，累计=%d\n",
                   round + 1, u, adj[u], u, lowcost[u], total);
        }

        /* 用新加入的 u 更新未入树点到树的距离 */
        for (int v = 0; v < V; v++) {
            if (!inTree[v] && g[u][v] < lowcost[v]) {
                lowcost[v] = g[u][v];
                adj[v] = u;
            }
        }
    }

    printf("\n最小生成树总权重 = %d\n", total);
    printf("\n与 Kruskal 对比：两者总权重应相同（本题均为 8），因为最小生成树的**总权重唯一**。\n");
    printf("差异在于：Prim 中间状态始终是一棵树（适合增量加点），Kruskal 是森林逐步合并（适合并行/分布式）。\n");
    return 0;
}
